/**
 * Cartes écrites à la main, en complément du classeur Excel.
 *
 * Sources de la recherche (sept. 2026) : histoire de l'IA (presse-citron,
 * theai.observer), AI Act (artificialintelligenceact.eu, service desk de la
 * Commission), entraînement des LLM (arxiv 2307.06435, zeroentropy.dev),
 * MCP (modelcontextprotocol.io, zenity.io), bases vectorielles (encore.dev,
 * tigerdata.com). Définitions en français ; les termes restent ceux du métier.
 *
 * Convention d'identifiant : `<matière>-x-<slug>` — le préfixe `x` évite toute
 * collision avec les identifiants générés depuis le classeur.
 */

import type { Card } from './types';

const card = (
  subject: string,
  topic: string,
  term: string,
  definition: string,
  example: string,
  level: Card['level'] = null,
  idPrefix: string = subject,
): Card => ({
  id: `${idPrefix}-x-${term
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')}`,
  subject,
  topic,
  level,
  term,
  definition,
  example,
  tags: ['#manual'],
});

const ia = (topic: string, term: string, definition: string, example: string, level: Card['level'] = null): Card =>
  card('ia', topic, term, definition, example, level);
const py = (topic: string, term: string, definition: string, example: string, level: Card['level'] = null): Card =>
  card('python', topic, term, definition, example, level);
/** HTML, CSS et JavaScript sont trois matières ; les identifiants gardent le préfixe historique `web-x-`. */
const WEB_SUBJECT: Record<string, string> = { html: 'html', 'web-mkt': 'html', css: 'css', js: 'js' };
const web = (topic: string, term: string, definition: string, example: string, level: Card['level'] = null): Card =>
  card(WEB_SUBJECT[topic] ?? 'js', topic, term, definition, example, level, 'web');

